/* ===== Parciales 2026 (18/11, pedido de Luca). Tema nuevo: lg5 tableaux (no estaba en ningún examen anterior). ===== */
/* --- Primer parcial, 28/4/2026 · Ejercicio 1: inducción sobre P⁺ --- */
lgEx("1P26 · Ej. 1 (inducción)","lg1",LGI.ind,["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 1 (10 puntos)",
 "a. Considere como alfabeto el conjunto P de letras proposicionales. De una definición inductiva del conjunto P⁺ de tiras no vacías de símbolos de P. Por ejemplo: p5 ∈ P⁺, p0 p1 ∈ P⁺, p0 p2 p0 ∈ P⁺",
 "b. Considere la definición inductiva del conjunto PROP∧,¬ de las fórmulas de PROP que solamente usan los conectivos ∧ y ¬: i. Si pi ∈ P entonces pi ∈ PROP∧,¬ · ii. Si α ∈ PROP∧,¬ y β ∈ PROP∧,¬ entonces (α ∧ β) ∈ PROP∧,¬ · iii. Si α ∈ PROP∧,¬ entonces (¬α) ∈ PROP∧,¬",
 "Defina la función obtenerLP : PROP∧,¬ → P⁺ que devuelve la tira de ocurrencias de letras proposicionales de una fórmula de PROP∧,¬. Por ejemplo: obtenerLP(p0) = p0 · obtenerLP((p0 ∧ p2)) = p0 p2 · obtenerLP((¬(p0 ∧ p0))) = p0 p0",
 "c. Demuestre por inducción que (∀w ∈ P⁺)(∃φ ∈ PROP∧,¬) obtenerLP(φ) = w.",
 "d. ¿Se cumple que para toda tira w de P⁺ existe una única fórmula φ de PROP∧,¬ tal que obtenerLP(φ) = w? Justifique su respuesta."],[
 {id:"a",k:"set",t:"a) el conjunto P⁺",p:"¿Qué cláusulas definen a P⁺?",ok:[["(i) Si pi ∈ P entonces pi ∈ P⁺","Cláusula base: una letra sola ya es una tira no vacía."],["(ii) Si w ∈ P⁺ y pi ∈ P entonces pi w ∈ P⁺","Cláusula inductiva: una letra adelante de una tira ya armada."]],
  no:[["(i) La tira vacía está en P⁺","P⁺ son las tiras NO vacías: la base es una letra."],["(ii) Si pi ∈ P y pj ∈ P entonces pi pj ∈ P⁺","Solo arma tiras de dos letras: p0 p2 p0 no se podría formar."],["(ii) Si w ∈ P⁺ entonces (¬w) ∈ P⁺","Las tiras de P⁺ son solo letras, sin conectivos."]]},
 {id:"b",k:"set",t:"b) la función obtenerLP",p:"¿Cómo se define obtenerLP, con un caso por cláusula de PROP∧,¬?",ok:[["obtenerLP(pi) = pi","Una letra da la tira de esa letra."],["obtenerLP((α ∧ β)) = obtenerLP(α) obtenerLP(β)","Las letras de cada lado, pegadas en orden."],["obtenerLP((¬α)) = obtenerLP(α)","El ¬ no agrega letras."]],
  no:[["obtenerLP((¬α)) = ¬obtenerLP(α)","El resultado es una tira de P⁺: solo letras, sin conectivos."],["obtenerLP((α ∧ β)) = obtenerLP(α) ∧ obtenerLP(β)","Las tiras no llevan ∧: se pegan una al lado de la otra."],["obtenerLP((α ∧ β)) = α β","α y β son fórmulas: hay que llamar a obtenerLP en cada lado."]]},
 {id:"c1",k:"set",t:"c) plan de la prueba",p:"¿Cómo se plantea la prueba por inducción?",mo:1,ok:[["Inducción sobre P⁺ (PIP para P⁺)","La afirmación empieza con (∀w ∈ P⁺): la variable de la inducción es la tira."],["Propiedad: Q(w) := (∃φ ∈ PROP∧,¬) obtenerLP(φ) = w",""],["Paso base: Q(pi)","La cláusula base de P⁺ es una letra sola."],["Paso inductivo: HI Q(w), TI Q(pi w)","La cláusula inductiva de P⁺ arma pi w a partir de w."]],
  no:[["Inducción sobre PROP∧,¬","El «para toda» es sobre las tiras; la fórmula es el testigo del ∃, no la variable de la inducción."],["Paso inductivo: HI Q(w), TI Q(w pi)","La cláusula inductiva de P⁺ pone la letra adelante: pi w."],["Paso base: Q(⊥)","La inducción es sobre P⁺: el caso base es una letra."]]},
 {id:"c2",k:"seq",t:"c) paso base",p:"Probá Q(pi): elegí el testigo y por qué sirve.",mo:1,sl:["testigo:",["φ := pi","Es de PROP∧,¬ por la regla i.","el testigo",["φ := (pi ∧ pi)","obtenerLP((pi ∧ pi)) = pi pi: tiene dos letras, no una."],["φ := ⊥","PROP∧,¬ no tiene ⊥ (y ⊥ no tiene letras)."]],"\n","porque",
   ["obtenerLP(pi) = pi (def. obtenerLP)","Se cumple directo por la definición.","el argumento",["obtenerLP(pi) = pi (HI)","En el paso base no hay hipótesis inductiva."]]]},
 {id:"c3",k:"seq",t:"c) paso inductivo: el testigo",p:"Por HI existe φ1 ∈ PROP∧,¬ con obtenerLP(φ1) = w. Elegí el testigo para pi w.",mo:1,sl:["testigo:",["φ2 := (pi ∧ φ1)","Es de PROP∧,¬ por la regla ii y sus letras son pi seguidas de las de φ1.","el testigo",["φ2 := (φ1 ∧ pi)","Daría w pi: la letra nueva quedaría al final, y hay que llegar a pi w."],["φ2 := (¬φ1)","obtenerLP((¬φ1)) = w: le falta la letra pi."]]]},
 {id:"c4",k:"cad",t:"c) paso inductivo: la cadena",p:"Con φ2 := (pi ∧ φ1), probá obtenerLP(φ2) = pi w.",mo:1,ini:"obtenerLP(φ2)",st:["= (def. φ2)   obtenerLP((pi ∧ φ1))","= (def. obtenerLP)   obtenerLP(pi) obtenerLP(φ1)","= (HI)   obtenerLP(pi) w","= (def. obtenerLP)   pi w"],
  no:[["= (def. obtenerLP)   obtenerLP(pi) ∧ obtenerLP(φ1)","obtenerLP pega las tiras: el resultado no lleva ∧."],["= (def. obtenerLP)   obtenerLP(pi) w","obtenerLP(φ1) = w no sale de la definición: sale de la HI (φ1 es el testigo que da la HI)."]]},
 {id:"d",k:"seq",t:"d) ¿la fórmula es única?",p:"Decidí y justificá la parte d.",mo:1,sl:["d:",["NO se cumple","Hay tiras que salen de más de una fórmula.","el veredicto",["SÍ se cumple","El ¬ no agrega letras: p0 y (¬p0) dan la misma tira."]],"\n","se justifica con",
   ["un contraejemplo: la tira p0 sale de p0 y de (¬p0)","Dos fórmulas distintas con la misma tira.","la justificación",["la parte c","La parte c prueba que existe una fórmula, no que sea única."],["un contraejemplo: las tiras p0 y p1 salen de fórmulas distintas","Eso no contradice nada: para romper la unicidad hacen falta dos FÓRMULAS con la MISMA tira."]]]}]);

/* --- Primer parcial · Ejercicio 2a: tableau semántico (tema nuevo lg5) --- */
lgEx("1P26 · Ej. 2a (tableau)","lg5",[],["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 2 (10 puntos)","Considere tres fórmulas α, β y φ de PROP.",
 "a. Determine mediante tableau semántico si: α ∧ β → φ ⊨ (α → φ) ∨ (β → φ)"],[
 {id:"a1",k:"seq",t:"a) la raíz del tableau",p:"¿Con qué empieza el tableau y cuándo vale la consecuencia?",sl:["la raíz lleva",["T.α ∧ β → φ  y  F.(α → φ) ∨ (β → φ)","Se busca una valuación que haga verdadera la premisa y falsa la conclusión (un contraejemplo).","la raíz",["T.α ∧ β → φ  y  T.(α → φ) ∨ (β → φ)","Así se buscaría un modelo de las dos. Para ⊨ se busca un contraejemplo: conclusión falsa."],["F.α ∧ β → φ  y  F.(α → φ) ∨ (β → φ)","El contraejemplo tiene que cumplir la premisa: va con T."]],"\n","la consecuencia vale si",
   ["todas las ramas cierran","Ninguna valuación hace verdadera la premisa y falsa la conclusión.","la condición",["alguna rama cierra","Una rama abierta y terminada ya es un contraejemplo: alcanza con una abierta para que ⊨ falle."]]]},
 {id:"a2",k:"set",t:"a) las reglas que se usan",p:"¿Qué hace cada regla de este tableau?",ok:[["F.A ∨ B ⇒ F.A y F.B en la misma rama","Un ∨ es falso solo si los dos lados son falsos."],["F.A → B ⇒ T.A y F.B en la misma rama","Un → es falso solo con antecedente verdadero y consecuente falso."],["T.A → B ⇒ dos ramas: F.A | T.B","Un → es verdadero si el antecedente es falso o el consecuente verdadero."],["F.A ∧ B ⇒ dos ramas: F.A | F.B","Un ∧ es falso si alguno de los dos es falso."]],
  no:[["T.A → B ⇒ F.A y T.B en la misma rama","Alcanza con una de las dos cosas: van en ramas separadas."],["F.A → B ⇒ dos ramas: F.A | T.B","Un → falso no tiene opciones: T.A y F.B a la vez, en la misma rama."],["F.A ∧ B ⇒ F.A y F.B en la misma rama","Basta con que uno sea falso: son dos ramas."]]},
 {id:"a3",k:"tab",t:"a) desarrollo del tableau",p:"Desarrollá el tableau: primero las reglas que no abren ramas, y cerrá cada rama apenas tenga T.X y F.X.",mo:1,ini:["T.α ∧ β → φ","F.(α → φ) ∨ (β → φ)"],st:[
   {t:"F.(α → φ) ∨ (β → φ) ⇒ F.α → φ, F.β → φ",add:["F.α → φ","F.β → φ"],mark:"F.(α → φ) ∨ (β → φ)"},{t:"F.α → φ ⇒ T.α, F.φ",add:["T.α","F.φ"],mark:"F.α → φ",dp:[0]},{t:"F.β → φ ⇒ T.β, F.φ",add:["T.β","F.φ"],mark:"F.β → φ",dp:[0]},
   {t:"T.α ∧ β → φ ⇒ ramas F.α ∧ β | T.φ",split:[["F.α ∧ β"],["T.φ"]],mark:"T.α ∧ β → φ",dp:[1,2]},{t:"rama T.φ: cierra con F.φ ×",close:"R",dp:[3]},
   {t:"rama F.α ∧ β ⇒ ramas F.α | F.β",at:"L",split:[["F.α"],["F.β"]],mark:"F.α ∧ β",dp:[3]},{t:"F.α cierra con T.α ×   y   F.β cierra con T.β ×",close:["LL","LR"],dp:[5]}],
  no:[["T.α ∧ β → φ ⇒ T.α, T.β → φ","El conectivo principal es →: α ∧ β → φ se lee (α ∧ β) → φ."],["F.α → φ ⇒ ramas F.α | T.φ","Esa es la regla de T.A → B. Un → falso da T.A y F.B en la misma rama."],["rama T.φ: queda abierta","En esa rama ya está F.φ (vino de F.α → φ): T.φ y F.φ la cierran."]]},
 {id:"a4",k:"seq",t:"a) conclusión",p:"¿Qué concluís del tableau?",mo:1,sl:["α ∧ β → φ ⊨ (α → φ) ∨ (β → φ)",["SE CUMPLE","Todas las ramas cerraron.","el veredicto",["NO se cumple","No quedó ninguna rama abierta: no hay contraejemplo."]],"\n","porque",
   ["ninguna valuación v cumple v(α ∧ β → φ) = 1 y v((α → φ) ∨ (β → φ)) = 0","Cada rama cerrada es un intento de contraejemplo que fracasa.","el argumento",["hay una valuación con v(α ∧ β → φ) = 1 y v((α → φ) ∨ (β → φ)) = 1","Que haya una donde las dos valen no prueba nada: ⊨ habla de TODAS las valuaciones."]]]}]);

/* --- Primer parcial · Ejercicio 2b y 2c: semántica y equivalencias --- */
lgEx("1P26 · Ej. 2bc (semántica)","lg2",LGI.sem,["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 2 (10 puntos)","Considere tres fórmulas α, β y φ de PROP.",
 "b. Demuestre que si β ⊨ φ, y α eq β ∧ φ, entonces α eq β","c. Demuestre mediante equivalencias que las siguientes fórmulas son equivalentes: (α → β) ∧ ¬β y ¬(β ∨ α)"],[
 {id:"b1",k:"seq",t:"b) cómo empieza la prueba",p:"H1) β ⊨ φ · H2) α eq β ∧ φ · T) α eq β. ¿Cómo arrancás?",sl:["Sea",["v una valuación genérica","H1, H2 y la tesis hablan de toda valuación.","el comienzo",["v una valuación con v(β) = 1","Hay que probar v(α) = v(β) para TODA v, también cuando v(β) = 0."]],"\n","de H1 sale",
   ["v(β) = mín{v(β), v(φ)}   (A)","Si v(β) = 1, v(φ) = 1; si v(β) = 0, el mínimo es 0. En los dos casos el mínimo es v(β).","lo que sale de H1",["v(β) = v(φ)","β ⊨ φ no da igualdad: si v(β) = 0, v(φ) puede valer 1."],["v(φ) = mín{v(β), v(φ)}","Si v(β) = 0 y v(φ) = 1, el mínimo es 0 ≠ v(φ)."]]]},
 {id:"b2",k:"cad",t:"b) la cadena desde H2",p:"Con (A), llevá H2 hasta la tesis.",mo:1,ini:"α eq β ∧ φ",st:["⇔ (def. eq)   v(α) = v(β ∧ φ)","⇔ (def. valuación)   v(α) = mín{v(β), v(φ)}","⇔ ((A))   v(α) = v(β)","⇔ (v genérica y def. eq)   α eq β"],
  no:[["⇔ (def. valuación)   v(α) = máx{v(β), v(φ)}","máx es la valuación de ∨; la de ∧ es mín."],["⇔ ((A))   v(α) = v(φ)","(A) dice que el mínimo vale v(β), no v(φ)."]]},
 {id:"c",k:"cad",t:"c) cadena de equivalencias",p:"Llevá (α → β) ∧ ¬β hasta ¬(β ∨ α).",mo:1,ini:"(α → β) ∧ ¬β",st:["eq (equivalencia →)   (¬α ∨ β) ∧ ¬β","eq (conmutativa)   ¬β ∧ (¬α ∨ β)","eq (distributiva)   (¬β ∧ ¬α) ∨ (¬β ∧ β)","eq (bottom)   (¬β ∧ ¬α) ∨ ⊥","eq (neutro)   ¬β ∧ ¬α","eq (De Morgan)   ¬(β ∨ α)"],
  no:[["eq (equivalencia →)   (α ∨ ¬β) ∧ ¬β","α → β eq ¬α ∨ β: se niega el antecedente."],["eq (distributiva)   (¬β ∨ ¬α) ∧ (¬β ∨ β)","Esa distribuye ∨ sobre ∧. Acá hay ¬β ∧ (… ∨ …): se distribuye el ∧."],["eq (De Morgan)   ¬(β ∧ α)","De Morgan cambia el conectivo: ¬β ∧ ¬α eq ¬(β ∨ α)."]]}]);

/* --- Primer parcial · Ejercicio 4: completo, consistente y maximal --- */
lgEx("1P26 · Ej. 4 (consistencia)","lg4",LGI.con,["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 4 (10 puntos)","Demuestre las siguientes afirmaciones:",
 "a. Existe un conjunto Γ1 ⊆ PROP completo tal que el conjunto ∆1 = {¬φ | φ ∈ Γ1} es consistente.","b. Existe un conjunto Γ2 ⊆ PROP consistente tal que el conjunto ∆2 = {¬φ | φ ∈ Γ2} es inconsistente.",
 "c. Para cualquier Γ3 ⊆ PROP, si Γ3 es consistente maximal, entonces ∆3 = {¬φ | φ ∈ Γ3} no es consistente maximal.","Se recuerda que un conjunto ∆ ⊆ PROP es completo si y solo si: ∆ es consistente y para todo φ ∈ PROP se cumple: ∆ ⊢ φ o ∆ ⊢ ¬φ."],[
 {id:"a",k:"seq",t:"a) Γ1 completo con ∆1 consistente",p:"Elegí Γ1 y justificá.",sl:["Γ1 :=",["P (todas las letras proposicionales)","La única valuación que lo satisface hace 1 a todas las letras.","el conjunto",["{p0}","Lo satisfacen muchas valuaciones (p1 queda libre): no es completo."],["{¬⊥}","¬⊥ vale en toda valuación: no decide ninguna letra, no es completo."]],"\n","Γ1 es completo porque",
   ["existe una única valuación que lo satisface","Caracterización semántica de la completitud.","por qué es completo",["es consistente","Consistente no alcanza: completo pide además Γ ⊢ φ o Γ ⊢ ¬φ para toda φ."]],"\n","∆1 = {¬pi | pi ∈ P} es consistente porque",
   ["la valuación que hace 0 a todas las letras lo satisface","Condición suficiente de consistencia.","por qué ∆1 es consistente",["Γ1 es completo","Eso no dice nada de las negaciones: hay que dar una valuación que satisfaga a ∆1."]]]},
 {id:"b",k:"seq",t:"b) Γ2 consistente con ∆2 inconsistente",p:"Elegí Γ2 y justificá.",mo:1,sl:["Γ2 :=",["{¬⊥}","Es consistente (¬⊥ vale siempre) y ∆2 = {¬¬⊥} deriva ⊥.","el conjunto",["{⊥}","Γ2 tiene que ser consistente, y {⊥} no lo es."],["{p0}","∆2 = {¬p0} es consistente: la valuación con v(p0) = 0 lo satisface."]],"\n","∆2 es inconsistente porque",
   ["¬¬⊥ ⊢ ⊥: suponiendo [⊥]¹, I¬ da ¬⊥, y E¬ con ¬¬⊥ da ⊥","Una derivación de ⊥ con hipótesis en ∆2.","el argumento",["¬¬⊥ es una tautología","v(¬¬⊥) = v(⊥) = 0: es una contradicción, no una tautología."]]]},
 {id:"c1",k:"seq",t:"c) la idea",p:"Sea Γ3 consistente maximal arbitrario. ¿Qué fórmula de Γ3 usás?",mo:1,sl:["en Γ3 está",["¬⊥, porque un consistente maximal contiene a todos los teoremas","Su negación ¬¬⊥ deriva ⊥ (parte b).","la fórmula",["⊥","Un conjunto consistente no contiene a ⊥."],["p0","No todo consistente maximal tiene a p0: puede tener a ¬p0."]]]},
 {id:"c2",k:"cad",t:"c) la cadena",p:"Desde ¬⊥ ∈ Γ3, llegá a que ∆3 no es consistente maximal.",mo:1,ini:"¬⊥ ∈ Γ3",st:["⇒ (teoría de conjuntos)   ¬¬⊥ ∈ {¬φ | φ ∈ Γ3}","⇒ (def. ∆3)   ¬¬⊥ ∈ ∆3","⇒ (derivación de la parte b)   ∆3 ⊢ ⊥","⇒ (def. consistente)   ∆3 es inconsistente, así que no es consistente maximal"],
  no:[["⇒ (def. ∆3)   ¬⊥ ∈ ∆3","∆3 tiene las negaciones de las fórmulas de Γ3: de ¬⊥ sale ¬¬⊥."],["⇒ (derivación de la parte b)   ∆3 ⊬ ⊥","La parte b derivó ⊥ desde ¬¬⊥: ∆3 ⊢ ⊥."]]}]);

/* --- Segundo parcial, 10/7/2026 · Ejercicio 1: términos cerrados e inducción --- */
lgEx("2P26 · Ej. 1 (inducción)","lg1",LGI.ind,["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 1 (15 puntos)","Sea un lenguaje de primer orden con igualdad de tipo de similaridad ⟨−; 1, 2; 1⟩ con símbolos de funciones f y g y símbolo de constante c.",
 "a. Defina TERMC, el conjunto de términos cerrados del lenguaje.","b. Defina una función siguiendo el ERP para TERMC: Cambiar : TERMC → TERMC que convierte todas las ocurrencias de f por g, duplicando el parámetro. Por ejemplo: Cambiar(f(c)) = g(c, c) · Cambiar(g(c, f(c))) = g(c, g(c, c)) · Cambiar(f(g(c, c))) = g(g(c, c), g(c, c)) · Cambiar(f(f(c))) = g(g(c, c), g(c, c))",
 "c. Sea la estructura M = ⟨N, ∗2, +, 1⟩, donde la función ∗2 retorna el resultado de multiplicar un natural por 2. Demuestre por inducción que: (∀t ∈ TERMC)(t^M = Cambiar(t)^M)"],[
 {id:"a",k:"set",t:"a) el conjunto TERMC",p:"¿Qué cláusulas definen a TERMC?",ok:[["(i) c ∈ TERMC","Base: la constante."],["(ii) Si t ∈ TERMC, entonces f(t) ∈ TERMC","f es unaria (el 1 del tipo)."],["(iii) Si t1, t2 ∈ TERMC, entonces g(t1, t2) ∈ TERMC","g es binaria (el 2 del tipo)."]],
  no:[["(i) Si x es una variable, x ∈ TERMC","Los términos CERRADOS no tienen variables: la base es solo c."],["(iii) Si t ∈ TERMC, entonces g(t) ∈ TERMC","El tipo ⟨−; 1, 2; 1⟩ dice que g lleva dos argumentos."],["(ii) Si t ∈ TERMC, entonces f(t, t) ∈ TERMC","f es unaria; el que duplica el parámetro es Cambiar, en la parte b."]]},
 {id:"b",k:"set",t:"b) la función Cambiar",p:"¿Cómo se define Cambiar, con un caso por cláusula de TERMC?",ok:[["Cambiar(c) = c","No hay f que cambiar."],["Cambiar(f(t)) = g(Cambiar(t), Cambiar(t))","f pasa a g con el parámetro duplicado, y se sigue cambiando adentro."],["Cambiar(g(t1, t2)) = g(Cambiar(t1), Cambiar(t2))","g se conserva; se cambia adentro."]],
  no:[["Cambiar(f(t)) = g(t, t)","Adentro de t puede haber más f: mirá Cambiar(f(f(c))) = g(g(c, c), g(c, c))."],["Cambiar(g(t1, t2)) = g(t1, t2)","Adentro puede haber f: Cambiar(g(c, f(c))) = g(c, g(c, c))."],["Cambiar(f(t)) = f(Cambiar(t))","Hay que sacar la f: va g con el parámetro duplicado."]]},
 {id:"c1",k:"set",t:"c) plan de la prueba",p:"¿Cómo se plantea la prueba por inducción?",mo:1,ok:[["Propiedad: P(t) := t^M = Cambiar(t)^M","PIP para TERMC."],["Paso base: P(c)",""],["Paso inductivo de f: HI P(t), TI P(f(t))",""],["Paso inductivo de g: HI P(t1) y P(t2), TI P(g(t1, t2))","Dos argumentos: una HI para cada uno."]],
  no:[["Paso inductivo de g: HI P(t1), TI P(g(t1, t2))","g arma el término con dos partes: hace falta la HI para las dos."],["Paso base: P(x) para cada variable x","Los términos cerrados no tienen variables."],["Inducción sobre N","La propiedad es (∀t ∈ TERMC): el PIP es el de TERMC, aunque el universo de M sea N."]]},
 {id:"c2",k:"seq",t:"c) paso base",p:"Probá P(c): c^M = Cambiar(c)^M.",mo:1,sl:["se cumple porque",["Cambiar(c) = c por def. de Cambiar, así que Cambiar(c)^M = c^M","Sale directo de la definición.","el argumento",["c^M = Cambiar(c)^M por HI","En el paso base no hay hipótesis inductiva."],["c^M = 1 y Cambiar(c)^M = 2","Cambiar(c) = c: no cambia nada, y los dos se interpretan como 1."]]]},
 {id:"c3",k:"cad",t:"c) paso inductivo de f",p:"Con la HI t^M = Cambiar(t)^M, probá Cambiar(f(t))^M = f(t)^M.",mo:1,ini:"Cambiar(f(t))^M",st:["= (def. Cambiar)   g(Cambiar(t), Cambiar(t))^M","= (def. M e interpretación de g)   Cambiar(t)^M + Cambiar(t)^M","= (HI)   t^M + t^M","= (aritmética)   2 ∗ t^M","= (def. M e interpretación de f)   f(t)^M"],
  no:[["= (def. M e interpretación de g)   Cambiar(t)^M ∗ Cambiar(t)^M","En M = ⟨N, ∗2, +, 1⟩ las funciones van en el orden del tipo: f es ∗2 y g es +."],["= (def. Cambiar)   g(t, t)^M","Cambiar(f(t)) = g(Cambiar(t), Cambiar(t)): se sigue cambiando adentro."],["= (HI)   f(t)^M","La HI habla de t, no de f(t): usarla así es suponer la tesis."]]},
 {id:"c4",k:"cad",t:"c) paso inductivo de g",p:"Con las HI t1^M = Cambiar(t1)^M y t2^M = Cambiar(t2)^M, probá Cambiar(g(t1, t2))^M = g(t1, t2)^M.",mo:1,ini:"Cambiar(g(t1, t2))^M",st:["= (def. Cambiar)   g(Cambiar(t1), Cambiar(t2))^M","= (def. M e interpretación de g)   Cambiar(t1)^M + Cambiar(t2)^M","= (HI1 y HI2)   t1^M + t2^M","= (def. M e interpretación de g)   g(t1, t2)^M"],
  no:[["= (def. M e interpretación de g)   2 ∗ Cambiar(t1)^M","∗2 es la interpretación de f; g es la suma de sus dos argumentos."],["= (HI1 y HI2)   g(t1, t2)^M","Las HI hablan de t1 y t2: primero hay que interpretar g para que aparezcan sus valores."]]}]);

/* --- Segundo parcial · Ejercicio 2: estructuras con igualdad --- */
lgEx("2P26 · Ej. 2 (modelos)","lg4",LGI.mod,["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 2 (15 puntos)","Considere un lenguaje de primer orden con igualdad, con tipo de similaridad ⟨−; −; 0⟩. Sean las siguientes definiciones:",
 "α := (∀x)(∀y)(∀z)(x =′ y ∨ x =′ z ∨ y =′ z)    β := (∃x)(∃y)(¬x =′ y)","a. Dé dos estructuras M1, M2 con universos de cardinalidad distinta que modelen α.","b. Dé una estructura Mb tal que Mb ⊨ α y Mb ⊭ β.","c. Dé una fórmula φ ∈ FORM tal que Mc ⊨ φ y ⊭ φ, donde Mc = ⟨{◦, □, △}⟩."],[
 {id:"A",k:"cad",t:"qué cumple un modelo de α",p:"Sea M = ⟨U⟩ genérica. Abrí M ⊨ α hasta una condición sobre U.",ini:"M ⊨ (∀x)(∀y)(∀z)(x =′ y ∨ x =′ z ∨ y =′ z)",st:["⇔ (2.4.5 y sust.)   (∀a, b, c ∈ U) M ⊨ (ā =′ b̄ ∨ ā =′ c̄ ∨ b̄ =′ c̄)","⇔ (2.4.5)   (∀a, b, c ∈ U)(M ⊨ ā =′ b̄ o M ⊨ ā =′ c̄ o M ⊨ b̄ =′ c̄)","⇔ (def. ⊨)   (∀a, b, c ∈ U)(v^M(ā =′ b̄) = 1 o v^M(ā =′ c̄) = 1 o v^M(b̄ =′ c̄) = 1)","⇔ (def. v^M)   (∀a, b, c ∈ U)(a = b o a = c o b = c)   (A)"],
  no:[["⇔ (2.4.5 y sust.)   (∃a, b, c ∈ U) M ⊨ (ā =′ b̄ ∨ ā =′ c̄ ∨ b̄ =′ c̄)","Un ∀ de la fórmula pasa a «para todo elemento del universo»."],["⇔ (2.4.5)   (∀a, b, c ∈ U)(M ⊨ ā =′ b̄ y M ⊨ ā =′ c̄ y M ⊨ b̄ =′ c̄)","El ∨ pasa a «o», no a «y»."]]},
 {id:"B",k:"seq",t:"qué cumple un modelo de β",p:"Abrí M ⊨ β de la misma forma.",mo:1,sl:["M ⊨ β ⇔",["(∃a ∈ U)(∃b ∈ U) a ≠ b   (B)","M ⊨ ¬ā =′ b̄ es M ⊭ ā =′ b̄, o sea v^M(ā =′ b̄) = 0.","la condición",["(∀a ∈ U)(∀b ∈ U) a ≠ b","El ∃ de la fórmula pasa a «existe un elemento», no a «todos»."],["(∃a ∈ U)(∃b ∈ U) a = b","β tiene ¬x =′ y: hace falta un par de elementos distintos."]]]},
 {id:"a",k:"seq",t:"a) dos modelos de α",p:"Elegí M1 y M2.",mo:1,sl:["M1 =",["⟨{◦}⟩","Con un solo elemento, a = b siempre.","la primera",["⟨∅⟩","El universo de una estructura no puede ser vacío."]],"\n","M2 =",
   ["⟨{◦, □}⟩","Con dos elementos, entre a, b y c dos tienen que coincidir.","la segunda",["⟨{◦, □, △}⟩","Con a = ◦, b = □, c = △ falla (A): no modela α."]],"\n","porque",
   ["en un universo de uno o dos elementos, entre a, b y c alguno se repite: se cumple (A)","Es la condición (A).","el argumento",["los universos tienen cardinalidad distinta","Eso lo pide la letra, pero no prueba que modelen α."]]]},
 {id:"b",k:"seq",t:"b) Mb ⊨ α y Mb ⊭ β",p:"Elegí Mb y justificá.",mo:1,sl:["Mb =",["M1 = ⟨{◦}⟩","Modela α (parte a) y no tiene dos elementos distintos.","la estructura",["M2 = ⟨{◦, □}⟩","◦ ≠ □: M2 modela β."]],"\n","Mb ⊭ β porque",
   ["por (B) habría que tener a ≠ b en {◦}, o sea ◦ ≠ ◦, que es falso","Un universo unitario no tiene dos elementos distintos.","el argumento",["Mb no modela α","Sí lo modela (parte a): lo que falla es β."]]]},
 {id:"c",k:"seq",t:"c) Mc ⊨ φ y ⊭ φ",p:"Elegí φ y justificá las dos cosas.",mo:1,sl:["φ :=",["β","Mc tiene dos elementos distintos y M1 no.","la fórmula",["α","En Mc = ⟨{◦, □, △}⟩ no vale α: ◦, □ y △ son tres distintos."],["¬β","En Mc hay dos elementos distintos: Mc ⊭ ¬β."]],"\n","⊭ φ porque",
   ["M1 ⊭ β (parte b)","⊭ φ dice que existe una estructura donde φ falla: M1 es testigo.","la primera razón",["ninguna estructura modela β","Mc la modela. ⊭ φ pide solo UNA estructura donde falle."]],"\n","Mc ⊨ φ porque",
   ["a = ◦ y b = □ cumplen (B)","Un par de elementos distintos de Mc.","la segunda razón",["a = ◦ y b = ◦ cumplen (B)","(B) pide a ≠ b."]]]}]);

/* --- Segundo parcial · Ejercicio 4: Mod, Th, Cons y consistencia --- */
lgEx("2P26 · Ej. 4 (consistencia)","lg4",LGI.con,["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 4 (15 puntos)","Sea L un lenguaje de primer orden con igualdad, con tipo de similaridad ⟨−; 1; 0⟩, con símbolo de función f. Considere el conjunto: Γ = {(∀x)(∀y)(¬x =′ y → ¬f(x) =′ f(y))} ⊆ SENT y sea M1 la siguiente estructura: M1 = ⟨{0, 1}, id⟩",
 "a. Demuestre que M1 ∈ Mod(Γ).","b. Demuestre que Cons(Γ) ⊆ Th({M1}).","c. Considere la sentencia φ = (∀x)f(x) =′ x. Demuestre que φ ∉ Cons(Γ).","d. Determine si se cumple que Cons(Γ) = Th({M1}). Justifique.","e. ¿Cons(Γ) es consistente maximal? Justifique.",
 "Nota: Puede utilizar sin probar que para cualquier estructura M = ⟨U, F⟩, se cumple que: M ⊨ Γ ⇔ (∀a ∈ U)(∀b ∈ U)(a ≠ b ⇒ F(a) ≠ F(b)) y que M ⊨ φ ⇔ (∀a ∈ U) F(a) = a"],[
 {id:"a",k:"cad",t:"a) M1 ∈ Mod(Γ)",p:"Armá la cadena.",ini:"M1 ∈ Mod(Γ)",st:["⇔ (def. Mod)   M1 ⊨ Γ","⇔ (nota aplicada a M1)   (∀n, m ∈ {0, 1})(n ≠ m ⇒ id(n) ≠ id(m))","⇔ (def. id)   (∀n, m ∈ {0, 1})(n ≠ m ⇒ n ≠ m), que se cumple"],
  no:[["⇔ (def. Mod)   Γ ⊨ M1","Mod(Γ) son las estructuras M con M ⊨ Γ."],["⇔ (nota aplicada a M1)   (∀n ∈ {0, 1}) id(n) = n","Esa es la nota para φ, no para Γ."]]},
 {id:"b",k:"cad",t:"b) Cons(Γ) ⊆ Th({M1})",p:"Sea φ ∈ Cons(Γ) arbitraria. Llegá a φ ∈ Th({M1}).",mo:1,ini:"φ ∈ Cons(Γ)",st:["⇔ (def. Cons)   Γ ⊢ φ","⇔ (corrección y completitud)   Γ ⊨ φ","⇔ (def. ⊨)   (∀M)(M ⊨ Γ ⇒ M ⊨ φ)","⇒ (parte a: M1 ⊨ Γ)   M1 ⊨ φ","⇔ (def. Th)   φ ∈ Th({M1})"],
  no:[["⇔ (parte a: M1 ⊨ Γ)   M1 ⊨ φ","Solo vale ⇒: de M1 ⊨ φ no se vuelve a Γ ⊨ φ (habría que mirar todos los modelos de Γ)."],["⇔ (def. ⊨)   (∃M)(M ⊨ Γ y M ⊨ φ)","Γ ⊨ φ habla de TODOS los modelos de Γ."],["⇔ (completitud)   Γ ⊨ φ","Para ⊢ ⇔ ⊨ hacen falta las dos: corrección (⊢ ⇒ ⊨) y completitud (⊨ ⇒ ⊢)."]]},
 {id:"c",k:"seq",t:"c) φ ∉ Cons(Γ)",p:"¿Cómo se prueba y con qué estructura?",mo:1,sl:["hay que dar",["una estructura M con M ⊨ Γ y M ⊭ φ","φ ∉ Cons(Γ) es Γ ⊬ φ, que equivale a Γ ⊭ φ (corrección y completitud).","qué hay que mostrar",["una derivación de ¬φ desde Γ","No se pide eso: φ ∉ Cons(Γ) es Γ ⊬ φ, y se prueba con un contramodelo."]],"\n","por ejemplo",
   ["M2 = ⟨{0, 1}, F⟩ con F(0) = 1 y F(1) = 0","F es inyectiva (modela Γ) y F(0) = 1 ≠ 0 (no modela φ).","la estructura",["M1 = ⟨{0, 1}, id⟩","id(n) = n para todo n: M1 ⊨ φ."],["M2 = ⟨{0, 1}, F⟩ con F(0) = 1 y F(1) = 1","F(0) = F(1) con 0 ≠ 1: no es inyectiva, no modela Γ."]]]},
 {id:"d",k:"seq",t:"d) ¿Cons(Γ) = Th({M1})?",p:"Decidí y justificá.",mo:1,sl:["d:",["NO se cumple","Hay una sentencia de Th({M1}) que no está en Cons(Γ).","el veredicto",["SÍ se cumple","La parte b da solo ⊆, y la sentencia de la parte c está en Th({M1}) pero no en Cons(Γ)."]],"\n","porque",
   ["ψ := (∀x)f(x) =′ x está en Th({M1}) (id(n) = n) y no en Cons(Γ) (parte c)","Un elemento que está en uno y no en el otro.","el argumento",["Cons(Γ) ⊆ Th({M1}) (parte b)","Esa es una sola inclusión; la igualdad necesita la otra, y es justo la que falla."]]]},
 {id:"e",k:"seq",t:"e) ¿Cons(Γ) es consistente maximal?",p:"Decidí y justificá.",mo:1,sl:["e:",["NO es consistente maximal","Está incluido estrictamente en un conjunto consistente.","el veredicto",["SÍ es consistente maximal","Cons(Γ) ⊊ Th({M1}), que es consistente: se le pueden agregar fórmulas sin volverlo inconsistente."]],"\n","porque",
   ["Cons(Γ) ⊊ Th({M1}) (partes b y d) y Th({M1}) es consistente maximal (práctico 9), así que es consistente","Un maximal no puede estar incluido estrictamente en un consistente.","el argumento",["Cons(Γ) ⊆ Th({M1}) y Th({M1}) es consistente","Con ⊆ no alcanza: podrían ser iguales. Hace falta que la inclusión sea estricta (parte d)."]]]}]);
